-- China Undead test (docs/china-undead.md): two new Undead "Skin Type" choices per sex, "China" and "China (B)".
-- Each copies the Fresh choice's parts (hides the exposed-bone pieces 19xx/29xx/30xx, Fresh's cape geosets) and adds
-- the China body as a skinned model (a collection, the way retail adds Mechagnome arms or Dracthyr horns), drawn on
-- the character's own skeleton. The model files are new FileDataIDs 95450001 (male) and 95450009 (female) from
-- tools/looks/china_undead.py; they reach the client through the patched build (tools/tact/patch.py).
-- "China" and "China (B)" differ only in the skinned model's Flags (0 and 1; retail uses 1 on 20 of its rows, meaning
-- unknown). Requirement 55 = Bony's (shown in a normal client); Fresh's own (4975) needs the China client setting.
-- ChrCustomizationSkinnedModel has no hotfix table in the core, so its rows go in hotfix_blob as the client's record
-- bytes (layout 4C32AA8A: CollectionsFileDataID int32, GeosetType uint8, GeosetID, Modifier, Flags int32; no ID).
-- Hotfix push 9570000. Re-runnable; the DELETEs undo it. Restart the worldserver afterwards.

DELETE FROM `hotfix_data` WHERE `Id` = 9570000;
DELETE FROM `chr_customization_choice` WHERE `ID` IN (954601, 954602, 954603, 954604);
DELETE FROM `chr_customization_element` WHERE `ID` BETWEEN 9546001 AND 9546052;
DELETE FROM `hotfix_blob` WHERE `TableHash` = 1436347628 AND `RecordId` IN (954601, 954602, 954603, 954604);

  `ChrCustomizationVisReqID`, `SortOrder`, `UiOrderIndex`, `Flags`, `AddedInPatch`, `SoundKitID`, `SwatchColor1`, `SwatchColor2`,
  `VerifiedBuild`) VALUES
('China', 954601, 567, 55, 0, 3, 3, 0, 90001, 0, 0, 0, 70790), -- male
('China (B)', 954602, 567, 55, 0, 4, 4, 0, 90001, 0, 0, 0, 70790), -- male
('China', 954603, 568, 55, 0, 3, 3, 0, 90001, 0, 0, 0, 70790), -- female
('China (B)', 954604, 568, 55, 0, 4, 4, 0, 90001, 0, 0, 0, 70790); -- female



-- Send them to the client: ChrCustomizationChoice 0x681D0F3D, ChrCustomizationElement 0xD6D051EC, ChrCustomizationSkinnedModel 0x559CECEC
